-- Founder-only official topic seed v0.14.0.175. Never invent user comments.
-- Preserves existing topic IDs; repeatable by stable legacy_source_code guard.
INSERT INTO public.commons_topics(forum_code,title,body,author_user_id,author_label,is_official,is_pinned,is_locked,legacy_source_code,status)
SELECT i.forum_code,i.title,i.body,NULL,'Official Founders Team',true,
  (i.n IN (1,2,9,13,21,25,29)),false,'F600_OFFICIAL_V1_'||lpad(i.n::text,2,'0'),'published'
FROM (VALUES (1,'F600_HEADQUARTERS','Welcome to the Founding 600','This private Commons is for authenticated Founding Standard and Extended members. You can ask questions, share learning experiences, suggest features and report problems. The Founder''s Design Council is reserved for eligible Extended members. Read the rules before posting; never disclose private payment or account information.'),
(2,'F600_HEADQUARTERS','Founding membership benefits and boundaries','The founder number is permanent and cannot be reallocated. The approved separate-product purchase discount is 10% Standard or 20% Extended when earned; founding subscriptions do not discount their own recurring charges. Founder recognition is not permanent paid access, company ownership, dividends or corporate voting power.'),
(3,'F600_HEADQUARTERS','Official announcements, release notes and known issues','Official posts identify what changed, what remains unverified, which member pages are affected and where to report a regression. Source commits are not necessarily production releases. Members can comment with reproducible feedback; staff publish corrected status after verification.'),
(4,'F600_HEADQUARTERS','Community rules and moderation policy','Use evidence-based language, distinguish simulated from historical examples, respect members'' privacy and report harassment or scams. Do not publish passwords, invoices, unreleased assessment answers, manipulated securities recommendations or coordinated stock promotion.'),
(5,'F600_LOUNGE','Introduce yourself using your preferred display name','What part of market education are you focusing on? Share your learning goals without revealing a real name, location, medical information or trading account. Useful introductions describe areas of curiosity and which skills you would like to practice.'),
(6,'F600_LOUNGE','What concept finally made sense?','Describe a topic that improved after a chart, guided calculation or instructor explanation. What made it click, and what still needs clarification? This helps the curriculum team recognize effective explanations rather than judging anyone''s trading returns.'),
(7,'F600_LOUNGE','General founding-member questions','Ask about navigation, available tools, the learning journey or where to find a feature. Include the page or Lab topic and what you tried. Billing history, payment disputes and individual credentials should go to private Support.'),
(8,'F600_LOUNGE','Learning milestones and achievements','Share verified educational milestones and techniques that helped you study. If you discuss a hypothetical trading decision, label it as simulated. Do not use another learner''s future bars or answers to claim independent completion.'),
(9,'F600_BUGS','How to file a reproducible technical bug','Include the affected page, steps, expected behavior, actual behavior, device/browser, approximate timing and a screenshot with sensitive details removed. Keep billing records, API keys, passwords and customer identities out of public posts, including this private forum.'),
(10,'F600_BUGS','Report chart, candlestick or Tutor mismatches','When Talia''s explanation differs from a chart label, provide the Lab identifier, learning stage, visible fictional prices and what differs. Do not paste private assessment keys, future replay evidence or real order data unless permitted.'),
(11,'F600_BUGS','Report mobile and accessibility problems','Explain if a button cannot be reached with a keyboard, text clips at increased zoom, focus is lost, labels are missing or reduced-motion preferences are ignored. Include viewport/browser details and a non-sensitive reproduction path.'),
(12,'F600_BUGS','Report account and purchase interface problems safely','General interface defects belong here; a specific payment, charge, refund, address or subscription should be handled through private Dashboard Support. Moderators may move or redact posts that accidentally contain financial or personal information.'),
(13,'F600_SUGGESTIONS','Submit a feature request with a clear outcome','Describe the member problem, affected page, who benefits, a feasible improvement and how success could be verified. Staff should show Submitted, Under Review, Accepted, In Development, Released, Deferred or Declined with reasons.'),
(14,'F600_SUGGESTIONS','Dashboard and navigation improvements','Which controls are hard to find? Where is space wasted? Describe a concrete desktop or mobile workflow and how a redesigned side panel, top navigation or compact summary would help without degrading accessibility.'),
(15,'F600_SUGGESTIONS','Improve Talia''s teaching and remediation','Suggest changes to pacing, context-sensitive examples, visual linkage, explanations of terminology and independent practice. Examples should remain beginner-first and preserve the accepted 419-Lab teaching architecture.'),
(16,'F600_SUGGESTIONS','New Lab, Boot Camp or tool improvements','Identify an existing Lab or Boot Camp topic, the missing explanation or exercise, and a feasible improvement. Do not request automatic mastery, future-bar disclosure, unlicensed historical data or extra competencies beyond the approved 30.'),
(17,'F600_LEARNING','Candlestick components and body-to-range percentage','Review Open, High, Low and Close, bullish and bearish real bodies, range and percentages using completed simulated candles. Explain why a candle describes an observed interval but cannot predict the next bar.'),
(18,'F600_LEARNING','VWAP versus EMA9 and EMA20','Discuss the VWAP price-volume weighting method, exponential moving averages, session boundaries, and multiple timeframe context. Mention whether an example is synthetic, historical or an illustration; avoid guarantees or real-time trading signals.'),
(19,'F600_LEARNING','Price structure, HH/HL/LH/LL and failed breakouts','Define higher highs, higher lows, lower highs and lower lows using observed price pivots. Share what evidence was available at each pause; avoid hindsight bias when analyzing breakouts, pullbacks and failed continuation.'),
(20,'F600_LEARNING','Risk planning and reading time-and-sales','Discuss spreads, displayed liquidity, volume, tape limitations, simulated fill assumptions and predefined risk. Never encourage coordinated ticker buying or misrepresent simulated results as real executions.'),
(21,'F600_MEMBERSHIP','Standard versus Extended membership','The planned Standard founder renewal is $49.99 every 30 days, and Extended is $59.99 every 60 days. Extended offers additional Sparks, longer included-credit life and Design Council eligibility. Consult the official Store for actual current availability; this discussion is not a checkout.'),
(22,'F600_MEMBERSHIP','Founder discount and Lifetime Membership explained','Eligible founder purchase discounts are 10% Standard and 20% Extended, including on the separate list-price $2,499 Lifetime Membership. Founding recurring subscriptions remain full founding price without stacking an extra founder discount.'),
(23,'F600_MEMBERSHIP','Crownlight Sparks: included and purchased','Included Sparks are granted on verified paid cycles and expire under the tier''s post-period rule: 90 days Standard and 150 days Extended. Purchased Sparks do not expire. Educational explanations remain free; a skip turns an eligible practice into Study Only rather than independently correct credit.'),
(24,'F600_MEMBERSHIP','Changes, cancellation and privacy','Founding numbers stay permanently associated with their original accounts but do not automatically unlock premium content after paid access ends. To review actual renewals, charges, cancellations or refunds, open private Billing or Support, not a Commons post.'),
(25,'F600_COUNCIL','How Extended Founder website design voting works','Eligible Extended Founders receive one vote per official design ballot, independently of Sparks and spending. Ballots compare vetted, accessible options. Results cannot override account security, privacy rules, instructional integrity or operational necessities.'),
(26,'F600_COUNCIL','Side panel and top navigation design criteria','Consider discoverability, focus order, responsive behavior, keyboard use, screen-reader labels, information density and learning-task efficiency. Describe the workflow affected rather than voting solely on decoration.'),
(27,'F600_COUNCIL','Lab, Boot Camp and Talia visual designs','Suggest improvements to visual presentation, chart annotations, Tutor character presence and instruction flow. Proposals must preserve the educational method, hidden assessment answers, and content rights.'),
(28,'F600_COUNCIL','Founder''s Choice priority improvements','The Council may help choose one vetted member-experience development priority twice yearly. Selection indicates priority consideration, not a financial vote, guaranteed delivery or right to direct company employees.'),
(29,'F600_TRACKER','Meaning of every issue lifecycle status','Submitted is received; Under Review is triage; Accepted is approved; In Development means work is underway; Released requires verified Production; Deferred or Declined includes a rationale. Staff responses should identify evidence and next steps.'),
(30,'F600_TRACKER','Bug report triage and verification','Report reproducible problems with affected workflow, impact and expected behavior. Staff should distinguish unconfirmed reports from verified defects and post fixes with test evidence; sensitive customer cases remain private.'),
(31,'F600_TRACKER','Suggestions: how staff respond','A useful review explains the proposal''s scope, constraints, accessibility, privacy or financial impact and outcome. Approved ideas receive implementation updates; rejected or deferred ideas should receive a respectful reason.'),
(32,'F600_TRACKER','What qualifies as a released improvement?','Release status means code is merged into the correct source branch, deployed to the actual website and verified with appropriate tests. Community members can flag a regression without treating a draft PR as released.')) AS i(n,forum_code,title,body)
WHERE NOT EXISTS(SELECT 1 FROM public.commons_topics t WHERE t.legacy_source_code='F600_OFFICIAL_V1_'||lpad(i.n::text,2,'0'));